/**
 * SQL-first generated types (spec §12.3). Dev-only.
 *
 * Reads src/state/control-schema.sql, applies it to a temp DatabaseSync,
 * writes src/state/control-schema.generated.mjs (table → column list).
 * Runtime still uses query-kit / openLocalSql; a typed query-builder
 * package, if ever added, consumes the generated file. No native addon
 * for codegen at runtime. CI guards the generated file against drift.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { loadBuiltinSql } from "../src/persist/engine-load.mjs";

const sql = fs.readFileSync(new URL("../src/state/control-schema.sql", import.meta.url), "utf8");
const tmp = path.join(os.tmpdir(), `xclaw-schema-${process.pid}.sqlite`);
const { DatabaseSync } = loadBuiltinSql();
const db = new DatabaseSync(tmp);
db.exec(sql);
const tables = db
  .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
  .all();
const out = {};
for (const { name } of tables) {
  out[name] = db.prepare(`PRAGMA table_info(${name})`).all().map((c) => c.name);
}
db.close();
fs.rmSync(tmp, { force: true });
fs.writeFileSync(
  new URL("../src/state/control-schema.generated.mjs", import.meta.url),
  "/** Generated by scripts/gen-control-types.mjs (spec §12.3) — do not edit. */\n" +
    "export const CONTROL_COLUMNS = " +
    JSON.stringify(out, null, 2) +
    ";\n",
);
console.log(`[gen-control-types] wrote ${Object.keys(out).length} table(s)`);
